import {spawn} from 'node:child_process';
import {mkdtemp,mkdir,rm,writeFile,readFile,readdir,unlink,stat} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {tmpdir} from 'node:os';
import {join,resolve} from 'node:path';
import {once} from 'node:events';
import http from 'node:http';
import net from 'node:net';
async function freePort(){const server=net.createServer();await new Promise((resolve,reject)=>{server.once('error',reject);server.listen(0,'127.0.0.1',resolve)});const port=server.address().port;await new Promise(resolve=>server.close(resolve));return port;}
async function stop(child){if(!child?.pid||child.exitCode!==null||child.signalCode!==null)return;const stopped=once(child,'exit');child.kill('SIGTERM');const timer=setTimeout(()=>child.kill('SIGKILL'),5000);try{await stopped;}finally{clearTimeout(timer);}}
/** Separate test controller; no approval/debug routes are added to production Agent localapi. */
export async function startM5Agent({origin,tls,binary=resolve('.runtime/m5-agent-fixture')}={}){
 const root=await mkdtemp(join(tmpdir(),'mcp-studio-m5-agent-')),control=join(root,'control'),cert=join(root,'fixture-ca.pem');await mkdir(control);await writeFile(cert,tls.cert,{mode:0o600});const port=await freePort(),address=`http://127.0.0.1:${port}`;let child,generation=0,ready=false,closed=false;const prompts=[],nativeProcesses=[],uploads=[],backups=[];let stdioCalls=0;
 const snapshot=()=>({generation,ready,address,prompts,nativeProcesses,uploads,backups,stdioCalls});
 const start=async()=>{ready=false;generation++;child=spawn(binary,[],{env:{...process.env,FIXTURE_AGENT_ROOT:root,FIXTURE_PLATFORM_ORIGIN:origin,FIXTURE_AGENT_LISTEN:`127.0.0.1:${port}`,FIXTURE_AGENT_CONTROL:control,FIXTURE_CA_FILE:cert},stdio:['ignore','pipe','pipe']});let failed=false;child.once('error',()=>{failed=true;});let buffer='';child.stdout.on('data',chunk=>{buffer+=chunk;let line;while((line=buffer.indexOf('\n'))>=0){const raw=buffer.slice(0,line);buffer=buffer.slice(line+1);let event;try{event=JSON.parse(raw);}catch{continue;}if(event.type==='ready')ready=true;else if(event.type==='native-pairing')prompts.push(event);else if(event.type==='native-process')nativeProcesses.push(event);else if(event.type==='upload')uploads.push(event);else if(event.type==='backup')backups.push(event);}});child.stderr.resume();const deadline=Date.now()+15000;while(!ready){if(failed||child.exitCode!==null||child.signalCode!==null)throw Error('Controlled Agent fixture exited during startup');if(Date.now()>deadline)throw Error('Controlled Agent fixture readiness timeout');await new Promise(resolve=>setTimeout(resolve,25));}};
 let controllerOrigin;const controller=http.createServer(async(req,res)=>{const reply=(status,value)=>{res.writeHead(status,{'Content-Type':'application/json','Cache-Control':'no-store'});res.end(JSON.stringify(value));};try{if(req.headers.host!==new URL(controllerOrigin).host)return reply(403,{error:'host'});if(req.method==='GET'&&req.url==='/state')return reply(200,snapshot());if(req.method==='POST'&&req.url==='/stdio-call'){stdioCalls++;return reply(200,{ok:true});}if(req.method==='POST'&&['/upload-failure','/vault-unavailable'].includes(req.url)){let raw='';for await(const chunk of req)raw+=chunk;const {enabled}=JSON.parse(raw);if(typeof enabled!=='boolean')return reply(400,{error:'input'});const flag=join(control,req.url==='/upload-failure'?'fail-uploads':'vault-unavailable');if(enabled)await writeFile(flag,'controlled fault',{mode:0o600});else await unlink(flag).catch(error=>{if(error.code!=='ENOENT')throw error;});return reply(200,{ok:true});}if(req.method==='POST'&&req.url==='/restart'){await stop(child);await start();return reply(200,{ok:true,generation});}if(req.method==='GET'&&req.url==='/disk-metadata'){const dir=join(root,'encrypted-data'),files=[];for(const name of (await readdir(dir)).sort()){if(!name.startsWith('credential-')||!name.endsWith('.bin'))continue;const content=await readFile(join(dir,name)),metadata=await stat(join(dir,name));files.push({name,sha256:createHash('sha256').update(content).digest('hex'),mtimeMs:metadata.mtimeMs,size:metadata.size});}return reply(200,{files});}if(req.method==='GET'&&req.url==='/disk'){const dir=join(root,'encrypted-data');const files=[];for(const name of await readdir(dir)){if(name.endsWith('.bin'))files.push({name,bytes:(await readFile(join(dir,name))).toString('base64')});}return reply(200,{files});}reply(404,{error:'missing'});}catch{reply(500,{error:'fixture_control_failed'});}});
 try{await new Promise((resolve,reject)=>{controller.once('error',reject);controller.listen(0,'127.0.0.1',resolve)});controllerOrigin=`http://127.0.0.1:${controller.address().port}`;await start();return {address,controllerOrigin,stdioCommand:binary,stdioArgs:['stdio',controllerOrigin],stats:()=>({generation,nativePairings:prompts.length,nativeProcesses:nativeProcesses.length,stdioCalls,uploads}),close:async()=>{if(closed)return;closed=true;try{await stop(child);}finally{controller.closeAllConnections();const results=await Promise.allSettled([new Promise(resolve=>controller.close(resolve)),rm(root,{recursive:true,force:true})]);if(results.some(result=>result.status==='rejected'))throw Error('Controlled Agent fixture cleanup failed');}}};}catch(error){try{await stop(child);}finally{controller.closeAllConnections();const results=await Promise.allSettled([new Promise(resolve=>controller.close(resolve)),rm(root,{recursive:true,force:true})]);if(results.some(result=>result.status==='rejected'))throw Error('Controlled Agent fixture cleanup failed');}throw error;}
}
